 * non-NULL, not-yet-initialized output pointer when deserialization fails.
 */
#include <stdint.h>
#include "obj.c"

static const uchar *g_data;
static size_t g_len;
static size_t g_pos;

static rsRetVal fakeReadChar(strm_t *pThis, uchar *pC)
{
	(void)pThis;
	if (g_pos >= g_len)
		return RS_RET_EOF;
	*pC = g_data[g_pos++];
	return RS_RET_OK;
}

static void set_input(const char *s, size_t n)
{
	g_data = (const uchar *)s;
	g_len = n;
	g_pos = 0;
}

int main(void)
{
	cstr_t *out;
	rsRetVal r;

	strm.ReadChar = fakeReadChar;

	/* Case 1 (negative): iLen=2 but the byte after the data is '!' not ':'.
	 * Emulate the uninitialized-but-non-NULL output variable of the caller. */
	set_input("ab!", 3);
	out = (cstr_t *)(uintptr_t)0xdeadbeefULL;
	r = objDeserializeStr(&out, 2, NULL);
	if (r != RS_RET_INVALID_DELIMITER) {
		fprintf(stderr, "NEG: unexpected rc %d\n", r);
		return 2;
	}
	if (out != NULL) {
		fprintf(stderr, "NEG-UNAFFECTED: out=%p left non-NULL after failure; "
			"caller cleanup would free an uninitialized pointer\n", (void *)out);
		return 3;
	}
	printf("NEG: terminator rejected; *ppCStr set to NULL (no uninitialized free)\n");

	/* Case 2 (positive): well-formed "ab:" string must still work. */
	set_input("ab:", 3);
	out = NULL;
	r = objDeserializeStr(&out, 2, NULL);
	if (r != RS_RET_OK || out == NULL) {
		fprintf(stderr, "POS: failed rc=%d out=%p\n", r, (void *)out);
		return 4;
	}
	if (strcmp((char *)rsCStrGetSzStrNoNULL(out), "ab") != 0) {
		fprintf(stderr, "POS: wrong content '%s'\n", rsCStrGetSzStrNoNULL(out));
		return 5;
	}
	cstrDestruct(&out);
	printf("POS: valid string accepted and destructed cleanly\n");

	/* Case 3: destructing a constructed but never-filled cstr (pBuf == NULL). */
	{
		cstr_t *empty = NULL;
		if (cstrConstruct(&empty) != RS_RET_OK)
			return 6;
		cstrDestruct(&empty);
		printf("STRBUF: destruct of cstr with NULL pBuf succeeded\n");
	}

	printf("RESULT: PASS\n");
	return 0;
}

