input.content:
/* Higher-level focused harness: drives the REAL objDeserializeProperty() from
 * runtime/obj.c (the actual caller of objDeserializeStr) with a corrupted
 * serialized string property, then emulates the var destructor clean-up.
 *
 * A previous property in the same var_t may have populated the val union with a
 * number/time, so a failed VARTYPE_STR parse leaves val.pStr aliasing that stale
 * non-NULL value.  The test asserts the fix normalizes it to NULL.
 */
#include "config.h"
#include <stdint.h>
#include "obj.c"

/* Minimal definitions for symbols referenced by the now-retained obj.c code
 * paths (debug output is disabled; Debug == 0). */
int Debug = 0;
void r_dbgprintf(const char *srcname, const char *fmt, ...)
{
	(void)srcname; (void)fmt;
}
void strmDebugOutBuf(const strm_t *const pThis)
{
	(void)pThis;
}
void LogError(const int iErrno, const int iErrCode, const char *fmt, ...)
{
	(void)iErrno; (void)iErrCode; (void)fmt;
}

static const uchar *g_data;
static size_t g_len;
static size_t g_pos;

static rsRetVal fakeReadChar(strm_t *pThis, uchar *pC)
{
	(void)pThis;
	if (g_pos >= g_len)
		return RS_RET_EOF;
	*pC = g_data[g_pos++];
	return RS_RET_OK;
}

static void set_input(const char *s, size_t n)
{
	g_data = (const uchar *)s;
	g_len = n;
	g_pos = 0;
}

int main(void)
{
	static const char line[] = "+pszRawMsg:1:2:ab!\n"; /* cookie, name, type=1(STR), len=2, "ab", bad terminator */
	var_t *v;
	rsRetVal r;
	int rc = 0;

	strm.ReadChar = fakeReadChar;

	v = (var_t *)calloc(1, sizeof(var_t));
	if (v == NULL)
		return 9;
	/* Emulate a stale union value from an earlier number/time property. */
	v->varType = VARTYPE_STR;
	v->val.pStr = (cstr_t *)(uintptr_t)0xdeadbeefULL;

	set_input(line, sizeof(line) - 1);
	r = objDeserializeProperty(v, NULL);

	if (r == RS_RET_OK) {
		fprintf(stderr, "PROP: unexpected success parsing corrupted property\n");
		rc = 4;
	} else if (v->varType == VARTYPE_STR && v->val.pStr != NULL) {
		fprintf(stderr, "PROP-UNAFFECTED: rc=%d but varType==VARTYPE_STR and val.pStr=%p "
			"stays non-NULL; caller destruct would free an uninitialized pointer\n",
			r, (void *)v->val.pStr);
		rc = 3;
	} else {
		printf("PROP: objDeserializeProperty rejected the corrupted string and left val.pStr NULL (safe)\n");
	}

	if (v->pcsName != NULL)
		rsCStrDestruct(&v->pcsName);
	free(v);
	return rc;
}

